#include <iostream>
#include <cstddef>

void inspectPointer(const int* ptr) {
    std::cout << "Inside function - sizeof(ptr): " << sizeof(ptr) << " bytes\n";
}

int main() {
    char c = 'Z';
    int arr[10];
    int* ptr = arr;

    std::cout << "sizeof(char): " << sizeof(c) << " byte\n";
    std::cout << "sizeof(int): " << sizeof(int) << " bytes\n";
    std::cout << "sizeof(double): " << sizeof(double) << " bytes\n";
    std::cout << "sizeof(arr) [10 ints]: " << sizeof(arr) << " bytes\n";
    std::cout << "sizeof(ptr) [pointer]: " << sizeof(ptr) << " bytes\n";

    inspectPointer(arr);

    std::size_t numElements = sizeof(arr) / sizeof(arr[0]);
    std::cout << "Calculated elements in arr: " << numElements << "\n";
    return 0;
}

#include <iostream>
#include <cstddef>

int main() {
    int v[5] = {100, 200, 300, 400, 500};
    int* vPtr = v;        // Points to v[0]
    int* v2Ptr = v + 3;   // Points to v[3] via pointer arithmetic

    std::cout << "Value at vPtr: " << *vPtr << "\n";
    std::cout << "Value at v2Ptr: " << *v2Ptr << "\n";

    // Difference between two pointers
    std::ptrdiff_t diff = v2Ptr - vPtr;
    std::cout << "v2Ptr - vPtr: " << diff << " elements\n";

    // C++17 explicit cast from generic void*
    void* genericPtr = vPtr + 2;
    int* concretePtr = static_cast<int*>(genericPtr);
    std::cout << "Value at concretePtr: " << *concretePtr << "\n";

    if (vPtr < v2Ptr) {
        std::cout << "vPtr points to an earlier index than v2Ptr\n";
    }
    return 0;
}
